css:
#loader-11 {
  width: 50px;
  aspect-ratio: 1;
  border: 2px solid;
  box-sizing: border-box;
  border-radius: 50%;
  display: grid;
  animation: l11 1.5s infinite linear;
  transform-origin: 50% 80%;
}
#loader-11::before,
#loader-11::after {
  content: "";
  grid-area: 1/1;
  border: inherit;
  border-radius: 50%;
  animation: inherit;
  animation-duration: 1s;
  transform-origin: inherit;
}
#loader-11::after {
  --s: -1;
}
@keyframes l11 {
  100% {transform: rotate(calc(var(--s, 1) * 1turn))}
}
